/* ---------- Grade 4 ---------- */
const PATH_ALL={c:{w1:'metal',w2:'metal',w3:'metal'},sw:'closed'};
mk(4,1,{t:'Close the loop',concept:'A complete circuit',goal:'Connect battery, wires, switch and bulb in one complete loop.',
  brief:'The path light circuit has two missing wires. Make one complete loop so the bulb lights.',
  predict:{q:'Will the bulb light with two wires missing?',o:[['yes','Yes'],['no','No']],r:[['loop','Electricity needs a complete loop'],['battery','The battery is connected'],['unsure','I’m not sure']]},
  play:{engine:'circuit',layout:'path',initial:{c:{w1:'metal',w2:null,w3:null},sw:'closed'},mats:['metal'],
    reqs:[['Test the circuit as you found it.',has((s,r)=>s.connectors.w2==null&&s.connectors.w3==null&&allOff(r))],['Complete the loop and test.',has((s,r)=>isClosed(s)&&allOn(r))]],
    steps:['First, test the circuit as you found it.','Add the supplied wire to each gap, then test.']},
  explain:[{q:'Which claim do your tests support?',o:[['loop','The bulb lit only when wires made a complete loop from the battery, through the bulb, and back.',1,'Yes. A complete conducting path is needed.'],['one','One wire from the battery is enough.',0,'Look at your first test.'],['bulb','The bulb lights if it touches the battery anywhere.',0,'Look at which tests lit the bulb.']]},
    {q:'Which tests show this?',o:[['pair','The test with gaps (off) and the complete test (on)',1,'Yes. Only the missing wires changed.'],['first','Only the test with gaps',0,'One test can’t show what made the difference.'],['none','No test shows it',0,'Compare your two tests.']]}],
  transfer:{intro:'The classroom lamp model.',fig:{type:'circuit',layout:'class',set:{c:{c1:'metal',c2:'metal',c3:null},sw:'closed'}},
    qs:[{q:'Will this lamp light?',o:[['no','No',1,'Right. Now find why.'],['yes','Yes',0,'Follow the path from + back to −.']]},
      {q:'Which part must be added to make a complete loop? Tap it or choose.',tap:true,o:[['c3','Switch back to battery −',1,'Yes. That gap breaks the loop.'],['c1','Battery + to lamp',0,'That wire is already there.'],['c2','Lamp to switch',0,'That wire is already there.'],['sw','Switch',0,'The switch is closed.']]}]},
  hints:{play:['Press Test first.','A bulb needs a complete loop from + to −.','Worked comparison: a loop with three wires and a closed switch lights the bulb. Which of yours are missing?'],explain:['Compare your two tests.','What changed?'],transfer:['Follow the path from +.','Where does the path stop?']},
  learned:'A bulb lights only when there is a complete loop of conducting material from the battery, through the bulb, and back.'});

mk(4,2,{t:'Choose a conductor',concept:'Conductors and insulators',goal:'Test materials in the gap to find which ones conduct.',
  brief:'The path light has a test gap. Try different materials in it. Which ones let the bulb light?',
  predict:{q:'Will a wooden stick in the gap light the bulb?',o:[['yes','Yes'],['no','No']],r:[['metal','Only some materials conduct'],['any','Anything that joins the gap works'],['unsure','I’m not sure']]},
  play:{engine:'circuit',layout:'path',initial:{c:{w1:'metal',w2:'metal',w3:null},sw:'closed'},edit:['w3'],mats:['metal','foil','clip','plastic','wood','string','rubber'],lockSwitch:true,
    reqs:[['Test at least four different materials in the gap.',T=>new Set(T.filter(x=>x.s.connectors.w3!=null).map(x=>x.s.connectors.w3)).size>=4],['Find a material that lights the bulb.',has((s,r)=>s.connectors.w3!=null&&allOn(r))],['Find a material that keeps the bulb off.',has((s,r)=>s.connectors.w3!=null&&allOff(r))]],
    steps:['Put a material in the test gap and press Test.','Try another material.','Keep testing until you have four.']},
  explain:[{q:'Which claim do your tests support?',o:[['metal','Metals conducted; plastic, wood, string and rubber didn’t.',1,'Yes. Conductors complete the loop; insulators don’t.'],['all','Every material conducts.',0,'Look at your tests with the bulb off.'],['long','The longest material worked best.',0,'Length didn’t change in this model.']]},
    {q:'Why was this a fair comparison?',o:[['fair','Only the material in the gap changed',1,'Yes. Battery, bulb, wires and switch stayed the same.'],['many','We tried lots of things at once',0,'Did more than one thing change each time?'],['none','It wasn’t fair',0,'What stayed the same?']]}],
  transfer:{intro:'A new gap in the classroom lamp.',fig:{type:'circuit',layout:'class',set:{c:{c1:'metal',c2:'rubber',c3:'metal'},sw:'closed'}},
    qs:[{q:'A rubber band joins the lamp to the switch. Will the lamp light?',o:[['no','No',1,'Right. Rubber is an insulator.'],['yes','Yes',0,'Is rubber a conductor?']]},
      {q:'Which would light it if used instead?',o:[['clip','A steel paper clip',1,'Yes. Metals conduct.'],['string','String',0,'Look at your string test.'],['wood','A wooden stick',0,'Look at your wood test.']]}]},
  hints:{play:['Tap the test gap to choose a material.','Try metals and non-metals.','Worked comparison: metal wire → on. Plastic → off.'],explain:['Group your tests: on and off.','What do the “on” materials have in common?'],transfer:['Is rubber like plastic or like metal?','Metals conduct.']},
  learned:'Conductors, like metals, let electricity pass and complete the loop. Insulators, like plastic, wood, string and rubber, don’t.'});

mk(4,3,{version:'2.0.0',t:'Find the hidden gap',concept:'A complete conducting path is needed',goal:'Find a gap that a closed switch can’t fix, then test whether the connector material matters.',
  brief:'The path light by the noticeboard won’t come on, and the switch is already closed. Use the circuit model to find out why.',
  predict:{q:'Will the path light come on when you press Test?',o:[['yes','Yes, it will light'],['no','No, it will stay off']],r:[['switch','The switch is closed'],['gap','Part of the path looks broken'],['battery','The battery might be flat'],['unsure','I’m not sure yet']]},
  play:{engine:'circuit',layout:'path',initial:{c:{w1:'metal',w2:'metal',w3:null},sw:'closed'},mats:['metal','plastic'],
    reqs:[['Test the circuit as you found it.',has(s=>isClosed(s)&&s.connectors.w1==='metal'&&s.connectors.w2==='metal'&&s.connectors.w3==null)],
      ['Fill the gap with the supplied wire and test again.',has((s,r)=>isClosed(s)&&vals(s).every(v=>v==='metal')&&allOn(r))],
      ['Swap one connector for plastic, keep the switch closed, and test.',has((s,r)=>isClosed(s)&&vals(s).filter(v=>v==='plastic').length===1&&vals(s).filter(v=>v==='metal').length===2&&allOff(r))]],
    steps:['First, test the circuit exactly as you found it.','The bulb is off. Follow the path, find the gap, and fill it with the supplied wire. Then test.','It works. Now swap one connector for plastic. Keep the switch closed and test again.']},
  explain:[{q:'Which claim do your tests support?',o:[['loop','The bulb lit only when metal made a complete loop from the battery, through the switch and bulb, and back.',1,'Yes. Each part of the loop has to conduct.'],['switch','A closed switch is enough to light the bulb.',0,'Look at your first test. The switch was closed, but the bulb stayed off.'],['usedup','The bulb uses up the current, so the wire after the bulb doesn’t matter.',0,'The gap was after the bulb, and the bulb stayed off until it was filled. Current flows around the whole loop.'],['plastic','Plastic works as long as the switch is closed.',0,'Look at your plastic test. The switch was closed, but the bulb was off.']]},
    {q:'Which tests are the best evidence that the material matters?',o:[['pair','The metal-wire test (bulb on) and the plastic test (bulb off). Only the connector material changed.',1,'Yes. Changing one thing at a time makes it a fair comparison.'],['first','Only the first test, when the bulb was off.',0,'One test shows the bulb was off, but not why.'],['any','Any test would do, because they all used the same battery.',0,'Which two tests changed only the material?']]}],
  transfer:{intro:'Someone built a model for the classroom lamp. The parts are in different places. The switch is closed.',fig:{type:'circuit',layout:'class',set:{c:{c1:'metal',c2:'plastic',c3:'metal'},sw:'closed'}},
    qs:[{q:'Will the lamp light when it is tested?',o:[['no','No, it will stay off',1,'Good prediction. Now find the part that keeps it off.'],['yes','Yes, it will light',0,'Check every part between the battery terminals, not just the switch.']]},
      {q:'Which part keeps the lamp off? Tap it on the drawing or choose below.',tap:true,o:[['c2','Lamp to switch',1,'Yes. Plastic doesn’t conduct, so the loop isn’t complete, even with the switch closed.'],['c1','Battery + to lamp',0,'That is a metal wire joined at both ends. Metal conducts.'],['c3','Switch back to battery −',0,'That is a metal wire joined at both ends. Metal conducts.'],['sw','Switch',0,'The switch is closed. It can’t make up for a break elsewhere.'],['loose','Loose wire',0,'That wire only crosses the drawing. It isn’t joined to any terminal, so it isn’t part of the loop.'],['bulb','Lamp',0,'The lamp itself is fine. Check the connectors.']]},
      {q:'Which evidence from the path light still applies here?',o:[['plastic','At the path light, plastic kept the bulb off even with the switch closed.',1,'Yes. Same idea, different circuit.'],['reclose','At the path light, closing the switch again fixed it.',0,'The switch was already closed at the path light.'],['none','Nothing carries over, because this is a different circuit.',0,'The layout is different, but the idea is the same.']]}]},
  hints:{play:['Press Test, then use Follow the path to look at every part.','A bulb needs a complete loop of conducting material from the battery, through the bulb, and back.','Worked comparison: three metal wires and a closed switch light the bulb. Which of your connectors is different?'],explain:['Look at your tests. When was the bulb on?','Compare the metal-wire test and the plastic test.'],transfer:['Follow the path from + all the way back to −.','A closed switch and lines that cross on the drawing don’t decide it. Each connector must conduct.']},
  learned:'A bulb lights only when there is a complete loop of conducting material from the battery, through the bulb, and back. A closed switch can’t make up for a gap or a plastic connector.'});

mk(4,4,{t:'Open and closed',concept:'What a switch does in a circuit',goal:'Test a complete circuit with the switch open and closed.',
  brief:'All the wires are in place. The switch is open. What does a switch actually do?',
  predict:{q:'With the switch open, will the bulb light?',o:[['yes','Yes'],['no','No']],r:[['gap','An open switch makes a gap'],['wires','All the wires are there'],['unsure','I’m not sure']]},
  play:{engine:'circuit',layout:'path',initial:{c:{w1:'metal',w2:'metal',w3:'metal'},sw:'open'},edit:[],mats:['metal'],
    reqs:[['Test with the switch open.',has((s,r)=>s.switches.sw==='open'&&allOff(r))],['Close the switch and test.',has((s,r)=>isClosed(s)&&allOn(r))]],
    steps:['Test with the switch open.','Tap the switch to close it, then test.']},
  explain:[{q:'Which claim do your tests support?',o:[['gap','An open switch makes a gap in the loop; closing it completes the loop.',1,'Yes. A switch opens and closes the path.'],['power','A switch makes electricity.',0,'The battery is the source. What changed between tests?'],['bulb','A switch makes the bulb brighter.',0,'Brightness isn’t modelled here. What changed?']]}],
  transfer:{intro:'The classroom lamp model.',fig:{type:'circuit',layout:'class',set:{c:{c1:'metal',c2:'metal',c3:'metal'},sw:'open'}},
    qs:[{q:'All wires are metal. The switch is open. Will the lamp light?',o:[['no','No',1,'Right. The open switch breaks the loop.'],['yes','Yes',0,'Is the loop complete?']]},
      {q:'Which one change would light it?',tap:true,o:[['sw','Close the switch',1,'Yes.'],['c1','Change the battery + wire',0,'That wire is fine.'],['loose','Move the loose wire',0,'The loose wire isn’t joined to anything.']]}]},
  hints:{play:['Test before you change anything.','Tap the switch to close it.','Worked comparison: open → off; closed → on.'],explain:['Compare your two tests.','What did the switch do to the loop?'],transfer:['Is the switch open or closed?','Open means a gap.']},
  learned:'A switch controls a circuit by opening a gap in the loop or closing it.'});

mk(4,5,{t:'Conductor or insulator',concept:'Classifying materials',goal:'Sort materials into conductors and insulators.',
  brief:'From your tests and what you know, sort these materials.',
  predict:{q:'Is a metal coin a conductor?',o:[['yes','Yes'],['no','No']]},
  play:{engine:'sort',instr:'Conductor or insulator?',bins:[['cond','Conductor'],['ins','Insulator']],
    items:[['spoon','Metal spoon','cond','Metals conduct.'],['foil','Aluminium foil','cond','It is a metal.'],['coin','Metal coin','cond','Metals conduct.'],['clip','Steel paper clip','cond','Steel is a metal.'],['ruler','Plastic ruler','ins','Plastic is an insulator.'],['stick','Wooden stick','ins','Dry wood is an insulator.'],['glass','Glass marble','ins','Glass is an insulator.'],['string','Cotton string','ins','String is an insulator.']]},
  explain:[{q:'Why are cable covers made of plastic?',o:[['ins','Plastic is an insulator, so it stops electricity reaching our hands',1,'Yes. The metal inside conducts; the plastic outside insulates.'],['cond','Plastic conducts well',0,'Look at your insulator group.'],['colour','It comes in nice colours',0,'Think about safety.']]}],
  transfer:{intro:'Building a model switch.',fig:{type:'scene',key:'island'},qs:[{q:'Which part of a model switch should be metal?',o:[['contact','The parts that touch to close the loop',1,'Yes. They must conduct.'],['handle','The handle you press',0,'Should your finger be part of the loop?'],['base','The base it sits on',0,'Should the base conduct?']]}]},
  hints:{play:['Ask: is it a metal?','Metals are conductors.','Worked example: foil → conductor; ruler → insulator.'],explain:['What does plastic do?','Look at your insulator group.'],transfer:['Which part carries electricity?','The touching contacts.']},
  learned:'Metals are conductors. Plastic, wood, glass and string are insulators.'});

mk(4,6,{t:'Three problems',concept:'Diagnosing several faults',goal:'Find and fix every fault in a circuit.',
  brief:'This path light has more than one problem. Find them all.',
  predict:{q:'How many problems do you think there are?',o:[['one','One'],['more','More than one']]},
  play:{engine:'circuit',layout:'path',initial:{c:{w1:'plastic',w2:'metal',w3:null},sw:'open'},mats:['metal','plastic'],
    reqs:[['Test the circuit as you found it.',has(s=>s.connectors.w1==='plastic'&&s.connectors.w3==null&&s.switches.sw==='open')],['Fix every fault and light the bulb.',has((s,r)=>allOn(r))]],
    steps:['Test the circuit as you found it.','Use Follow the path to find every fault, fix them, and test.']},
  explain:[{q:'What were the three problems?',o:[['three','An open switch, a plastic connector and a gap',1,'Yes. Any one of them would break the loop.'],['switch','Only the open switch',0,'Did closing the switch alone light the bulb?'],['battery','A flat battery',0,'Did the battery change?']]},
    {q:'Why did fixing just one problem not light the bulb?',o:[['each','Every break must be fixed for the loop to be complete',1,'Yes.'],['bulb','The bulb needed time',0,'Results don’t wait in this model.'],['luck','It was bad luck',0,'Follow the path after one fix.']]}],
  transfer:{intro:'Classroom lamp with problems.',fig:{type:'circuit',layout:'class',set:{c:{c1:null,c2:'metal',c3:'plastic'},sw:'closed'}},
    qs:[{q:'How many parts must be fixed?',o:[['two','Two: the gap and the plastic',1,'Yes.'],['one','One',0,'Follow the whole path.'],['three','Three',0,'Is the switch closed?']]}]},
  hints:{play:['Follow the path one part at a time.','Check the switch and every connector.','Worked comparison: the bulb lights only when the switch is closed and every connector is metal.'],explain:['List the parts you changed.','There were three.'],transfer:['Follow the path from +.','Count the breaks.']},
  learned:'A loop can have several breaks. All of them must be fixed before the bulb lights.'});

mk(4,7,{t:'Circuit symbols',concept:'Reading circuit diagrams',goal:'Match circuit symbols to the parts they show.',
  brief:'Circuit diagrams use symbols. Match each symbol to its part.',
  predict:{q:'Does the long line in the battery symbol show the + side?',o:[['yes','Yes'],['no','No']]},
  play:{engine:'sort',instr:'Which part does each symbol show?',bins:[['bat','Battery'],['sw','Switch'],['bulb','Bulb']],
    items:[['b1','Long and short lines (side on)','bat','Long line +, short line −.','symBattery'],['b2','Long and short lines (upright)','bat','Same symbol, turned around.','symBattery2'],['so','Lifted line between two dots','sw','An open switch.','symSwitchOpen'],['sc','Straight line between two dots','sw','A closed switch.','symSwitchClosed'],['bu','Circle with a cross','bulb','A bulb.','symBulb']]},
  explain:[{q:'How can you tell an open switch from a closed one?',o:[['gap','The open switch line is lifted, leaving a gap',1,'Yes.'],['colour','By colour',0,'Symbols don’t rely on colour.'],['size','The open one is bigger',0,'Look at the line.']]}],
  transfer:{intro:'A new diagram.',fig:{type:'circuit',layout:'path',set:{c:{w1:'metal',w2:'metal',w3:'metal'},sw:'open'}},qs:[{q:'Will this circuit light the bulb?',o:[['no','No: the switch symbol is open',1,'Yes. You read the symbol.'],['yes','Yes: all wires are there',0,'Look at the switch symbol.']]}]},
  hints:{play:['Look for circles, lines and dots.','A circle with a cross is a bulb.','Worked example: lifted line → open switch.'],explain:['Compare the two switch symbols.','One has a gap.'],transfer:['Find the switch symbol.','Is it lifted?']},
  learned:'Circuit symbols show each part. A lifted switch line means the switch is open.'});

mk(4,8,{t:'Follow the current path',concept:'Tracing a circuit',goal:'Put the parts of a loop in order from the battery and back.',
  brief:'Trace the loop of the path light, starting at the battery + terminal.',
  predict:{q:'Does the path end where it started?',o:[['yes','Yes, it returns to the battery'],['no','No, it stops at the bulb']]},
  play:{engine:'sequence',instr:'Put the parts in loop order.',cards:[['plus','Battery + terminal'],['w1','Wire to the switch'],['sw','Closed switch'],['w2','Wire to the bulb'],['bulb','Bulb filament'],['w3','Wire back to battery − terminal']]},
  explain:[{q:'Which statement fits the loop?',o:[['whole','Current flows around the whole loop and back to the battery.',1,'Yes. Nothing is used up along the way.'],['stops','Current stops at the bulb.',0,'Where does the loop end?'],['two','Current comes from both ends and meets at the bulb.',0,'Follow your order.']]}],
  transfer:{intro:'Classroom lamp loop.',fig:{type:'circuit',layout:'class',set:{c:{c1:'metal',c2:'metal',c3:'metal'},sw:'closed'}},qs:[{q:'Starting at battery +, what comes right after the first wire?',tap:true,o:[['bulb','The lamp',1,'Yes. In this layout the lamp comes before the switch.'],['sw','The switch',0,'Follow the wire from +.'],['loose','The loose wire',0,'It isn’t joined to anything.']]}]},
  hints:{play:['Start at +.','The switch comes before the bulb in this layout.','Worked example: + → wire → switch → wire → bulb → wire → −.'],explain:['Where does your order end?','Back at the battery.'],transfer:['Follow the wire from +.','Which part does it reach?']},
  learned:'In a loop, current flows from the battery, through every part, and back to the battery.'});

mk(4,9,{t:'Safe circuits only',concept:'The safety boundary',goal:'Sort what is safe to explore from what must never be touched.',
  brief:'Model circuits with a teacher are for learning. Some electricity is never for children to touch.',
  predict:{q:'Is a wall socket safe to explore?',o:[['yes','Yes'],['no','Never']]},
  play:{engine:'sort',instr:'Safe to explore, or never touch?',bins:[['ok','Safe with a teacher'],['never','Never touch']],
    items:[['kit','Battery-and-bulb kit with a teacher','ok','Low voltage, with supervision.'],['game','Circuits in this game','ok','They are pretend.'],['socket','Wall socket','never','Mains electricity can kill.'],['cable','Damaged cable','never','Keep away and tell an adult.'],['water','Electric things near water','never','Water and electricity are dangerous.'],['lines','Fallen power lines','never','Stay far away and tell an adult.']]},
  explain:[{q:'Why is a model battery circuit different from a wall socket?',o:[['low','The model uses a small battery; sockets carry dangerous mains electricity',1,'Yes. That’s why we only explore models.'],['same','They are the same',0,'Look at your never-touch group.'],['colour','Sockets are a different colour',0,'Think about danger.']]}],
  transfer:{intro:'At a friend’s house.',fig:{type:'scene',key:'island'},qs:[{q:'A friend wants to copy this game’s circuit using a wall socket. What do you say?',o:[['no','No. Never use sockets. Tell an adult.',1,'Yes. Completing this game doesn’t mean it’s safe to try real wiring.'],['yes','Yes, it’s the same',0,'Is a socket a model battery?'],['careful','Okay, if we are careful',0,'Sockets are never for children.']]}]},
  hints:{play:['Ask: is it a small model, or real mains electricity?','Sockets, damaged cables and power lines are never safe.','Worked example: kit with teacher → safe.'],explain:['Which is a small battery?','Which is mains?'],transfer:['Is a socket in your safe group?','Tell an adult.']},
  learned:'Only explore model circuits with a teacher. Never touch sockets, damaged cables or power lines.'});

mk(4,10,{t:'Fix the classroom lamp',concept:'Applying circuit ideas to a new layout',goal:'Diagnose and fix a circuit laid out differently.',
  brief:'The classroom lamp model doesn’t work. The parts are in new places, and a loose wire crosses the drawing.',
  predict:{q:'Will the lamp light as it is?',o:[['yes','Yes'],['no','No']],r:[['plastic','There is plastic in the loop'],['cross','The wires cross'],['unsure','I’m not sure']]},
  play:{engine:'circuit',layout:'class',initial:{c:{c1:'metal',c2:'plastic',c3:null},sw:'open'},mats:['metal','plastic'],
    reqs:[['Test the circuit as you found it.',has(s=>s.connectors.c2==='plastic'&&s.connectors.c3==null)],['Fix it and light the lamp.',has((s,r)=>allOn(r))]],
    steps:['Test the circuit as you found it.','Follow the path, fix every fault, and test.']},
  explain:[{q:'Did the loose wire matter?',o:[['no','No. It crosses the drawing but isn’t joined to any terminal.',1,'Yes. Crossing lines aren’t connections.'],['yes','Yes, it caused a short circuit',0,'Is it joined at either end?'],['fix','Yes, it fixed the gap',0,'Is it joined at either end?']]},
    {q:'What did you change?',o:[['all','Closed the switch, swapped plastic for metal, filled the gap',1,'Yes. Three breaks, three fixes.'],['loose','Moved the loose wire',0,'The loose wire can’t be moved.'],['bulb','Changed the bulb',0,'The lamp was fine.']]}],
  transfer:{intro:'Back at the path light.',fig:{type:'circuit',layout:'path',set:{c:{w1:'metal',w2:null,w3:'metal'},sw:'closed'}},qs:[{q:'Which part needs fixing?',tap:true,o:[['w2','Switch to bulb',1,'Yes. That gap breaks the loop.'],['sw','Switch',0,'It is closed.'],['w1','Battery + to switch',0,'That wire is metal and joined.']]}]},
  hints:{play:['Use Follow the path.','A crossing wire isn’t a connection.','Worked comparison: closed switch + all metal → lamp on.'],explain:['Is the loose wire joined to a terminal?','Look at its ends.'],transfer:['Follow the path from +.','Find the gap.']},
  learned:'The same rule works in any layout: every part of the loop must conduct. Wires that only cross on a drawing aren’t connected.'});

/* ---------- Grade 5 ---------- */
mk(5,1,{t:'Track the energy',concept:'Energy transfer in a circuit',goal:'Describe how energy is transferred from a battery to light and heat.',
  brief:'Where does the energy for the path light come from, and where does it go?',
  predict:{q:'Does the battery make energy from nothing?',o:[['yes','Yes'],['no','No, it stores energy']]},
  play:{engine:'sequence',instr:'Put the energy story in order.',cards:[['store','Energy is stored chemically in the battery'],['current','The circuit transfers energy electrically to the bulb'],['bulb','The bulb filament gets very hot'],['out','Energy spreads out as light and heat']]},
  explain:[{q:'Which statement is correct?',o:[['transfer','The battery stores energy; the circuit transfers it to the bulb, which gives out light and heat.',1,'Yes. Energy is transferred, not created.'],['create','The battery creates energy.',0,'Where did the energy start?'],['usedup','The bulb uses up the current.',0,'Current flows around the whole loop. Energy is what’s transferred.']]},
    {q:'What happens to the energy in the end?',o:[['spread','It spreads into the surroundings as light and heat',1,'Yes.'],['gone','It disappears',0,'Energy isn’t destroyed.'],['back','It goes back into the battery',0,'Look at your last card.']]}],
  transfer:{intro:'A battery fan.',fig:{type:'scene',key:'classroom'},qs:[{q:'A battery fan spins. Where does the energy go?',o:[['move','Into moving air, plus some sound and heat',1,'Yes. Same story, different output.'],['nowhere','Nowhere',0,'Energy has to go somewhere.'],['battery','Back into the battery',0,'Does the battery recharge as it runs?']]}]},
  hints:{play:['Start where the energy is stored.','The bulb comes before light and heat.','Worked example: battery → circuit → bulb → light and heat.'],explain:['Look at your first card.','Look at your last card.'],transfer:['What does a fan do?','It moves air.']},
  learned:'A battery stores energy. The circuit transfers it to the bulb, which gives it out as light and heat.'});

mk(5,2,{t:'Solar after sunset',concept:'Storing energy for night-time',goal:'Find what a solar path light needs to work at night.',scene:'solar',
  brief:'The path must be lit after dark. The panel is in open sun. What else does the system need?',
  predict:{q:'Will the panel alone light the lamp after dark?',o:[['yes','Yes'],['no','No']],r:[['store','It needs stored energy'],['sun','It saved sunlight in the panel'],['unsure','I’m not sure']]},
  play:{engine:'solar',initial:{panel:'yes',site:'sun',storage:'no',time:'night'},edit:['storage','time'],
    reqs:[['Test after dark with no battery store.',has((s,r)=>s.time==='night'&&s.storage==='no'&&!r.lit)],['Add a battery store and test after dark.',has((s,r)=>s.time==='night'&&s.storage==='yes'&&r.lit)]],
    steps:['Test after dark with no battery store.','Add a battery store and test after dark again.']},
  explain:[{q:'Which claim do your tests support?',o:[['store','A battery store, charged by day, supplies energy for the lamp at night.',1,'Yes. The panel can’t work without light.'],['panel','The panel works at night if it’s big.',0,'Look at your night test without a store.'],['moon','Moonlight powers it.',0,'Look at your night test without a store.']]},
    {q:'What did the store do?',o:[['stored','Stored energy from the day for use later',1,'Yes.'],['made','Made new energy at night',0,'Stores don’t make energy.'],['nothing','Nothing',0,'Compare your two night tests.']]}],
  transfer:{intro:'A boat jetty light.',fig:{type:'solar',set:{panel:'yes',site:'sun',storage:'no',time:'night'}},qs:[{q:'This jetty light has only a panel. It must work at night. What should be added?',o:[['store','A battery store',1,'Yes.'],['panel','A second panel',0,'Would a panel work after dark?'],['nothing','Nothing',0,'Look at your night test.']]}]},
  hints:{play:['Test before adding anything.','Use the Battery store buttons.','Worked comparison: night, no store → off. Night, store → on.'],explain:['Compare your two night tests.','What changed?'],transfer:['Does a panel work at night?','Add stored energy.']},
  learned:'A panel can’t make electricity in the dark. A battery store, charged by day, lights the lamp at night.'});

mk(5,3,{t:'A fair circuit comparison',concept:'Controlling variables',goal:'Compare connector materials, changing only one thing.',
  brief:'Is foil as good as metal wire? Is wood? Plan a fair comparison.',
  predict:{q:'To test the material fairly, what should you change?',o:[['one','Only the material'],['many','The material and the switch']]},
  play:{engine:'circuit',layout:'path',initial:{c:{w1:'metal',w2:'metal',w3:'metal'},sw:'closed'},edit:['w3'],mats:['metal','foil','wood','plastic'],
    reqs:[['Test with a conductor in the test connector.',has((s,r)=>isClosed(s)&&cond(s.connectors.w3)&&allOn(r))],
      ['Run a fair pair: change only the test connector’s material and test again.',T=>T.some(a=>T.some(b=>a!==b&&onlyDiffer(a.s,b.s,'w3')&&a.s.connectors.w3!=null&&b.s.connectors.w3!=null&&allOn(a.r)&&allOff(b.r)))]],
    steps:['Test with a conductor in the test connector (bulb back to battery).','Now change only that material to one you think won’t conduct, and test.']},
  explain:[{q:'Why is your pair a fair test?',o:[['one','Only the connector material changed; battery, bulb, other wires and switch stayed the same',1,'Yes. So the material caused the difference.'],['many','Lots of things changed',0,'Look at your test log.'],['luck','It was lucky',0,'What stayed the same?']]},
    {q:'What can you conclude?',o:[['material','The material in that connector decided whether the bulb lit.',1,'Yes. That’s a conclusion your evidence supports.'],['bright','Foil makes the bulb brighter than wire.',0,'Brightness wasn’t measured.'],['all','All materials behave the same.',0,'Look at your pair.']]}],
  transfer:{intro:'A classmate’s test.',fig:{type:'scene',key:'island'},qs:[{q:'A classmate swapped the battery AND the connector at the same time. What’s the problem?',o:[['two','Two things changed, so we can’t tell which caused the result',1,'Yes.'],['fine','Nothing; it’s fair',0,'How many things changed?'],['slow','It took too long',0,'Think about fairness.']]}]},
  hints:{play:['Only use the test connector.','Keep the switch and other wires the same.','Worked comparison: metal → on; then plastic in the same spot → off.'],explain:['Look at your two tests.','What changed between them?'],transfer:['Count the changes.','Fair tests change one thing.']},
  learned:'A fair test changes only one thing, so the result can be linked to that change.'});

mk(5,4,{t:'Energy outputs',concept:'Devices transfer energy in different ways',goal:'Sort devices by their main useful output.',
  brief:'Electric devices transfer energy into different useful forms.',
  predict:{q:'What is the main useful output of a rice cooker?',o:[['heat','Heat'],['light','Light']]},
  play:{engine:'sort',instr:'What is each device’s main useful output?',bins:[['light','Light'],['sound','Sound'],['move','Movement'],['heat','Heat']],
    items:[['lamp','Lamp','light','We use it to see.'],['torch','Torch','light','We use it to see.'],['radio','Radio','sound','We listen to it.'],['bell','Electric bell','sound','It rings.'],['fan','Fan','move','Its blades move air.'],['car','Toy car','move','It drives.'],['cooker','Rice cooker','heat','It cooks food.'],['iron','Clothes iron','heat','It smooths clothes.']]},
  explain:[{q:'A lamp also gets warm. Which statement is right?',o:[['main','Light is its useful output; the heat is also transferred but not wanted',1,'Yes. Devices often give more than one output.'],['heater','A lamp is mainly a heater',0,'What do we use a lamp for?'],['none','A lamp gives no heat',0,'Have you felt a warm bulb?']]}],
  transfer:{intro:'A new device.',fig:{type:'scene',key:'island'},qs:[{q:'A water pump moves water up to the tank. Its main useful output is…',o:[['move','Movement',1,'Yes.'],['light','Light',0,'What does a pump do?'],['sound','Sound',0,'Is the noise useful?']]}]},
  hints:{play:['Ask: why do we use it?','The main output is the job we want.','Worked example: radio → sound.'],explain:['Is the heat useful for a lamp?','What do we use a lamp for?'],transfer:['What does a pump do?','It moves water.']},
  learned:'Devices transfer energy into useful outputs like light, sound, movement or heat.'});

mk(5,5,{t:'Useful or wasted',concept:'Useful and wasted energy',goal:'Sort energy outputs into useful and wasted.',
  brief:'Devices often give out more than one kind of energy. Some is useful; some is wasted.',
  predict:{q:'For a lamp, is the heat useful?',o:[['useful','Useful'],['wasted','Wasted']]},
  play:{engine:'sort',instr:'Useful or wasted?',bins:[['useful','Useful'],['wasted','Wasted']],
    items:[['lamplight','Lamp: light','useful','We want to see.'],['lampheat','Lamp: heat','wasted','We don’t need the lamp to warm us.'],['fanair','Fan: moving air','useful','It cools us.'],['fannoise','Fan: humming sound','wasted','We don’t want the noise.'],['cookerheat','Rice cooker: heat','useful','It cooks rice.'],['radiosound','Radio: sound','useful','We listen.'],['radioheat','Radio: warmth','wasted','Nobody needs a warm radio.']]},
  explain:[{q:'Why is an LED bulb a good choice?',o:[['less','More of its energy becomes light and less is wasted as heat',1,'Yes. It is more efficient.'],['more','It makes more heat',0,'Is heat useful for a lamp?'],['free','It needs no energy',0,'All lamps need energy.']]}],
  transfer:{intro:'A heater.',fig:{type:'scene',key:'island'},qs:[{q:'For a room heater, the heat is…',o:[['useful','Useful',1,'Yes. Useful depends on the device’s job.'],['wasted','Wasted',0,'What is a heater’s job?']]}]},
  hints:{play:['Ask: what is this device’s job?','Outputs that don’t help the job are wasted.','Worked example: lamp light → useful; lamp heat → wasted.'],explain:['Which output is wasted in a lamp?','LEDs waste less.'],transfer:['What is a heater for?','Heat is its job.']},
  learned:'Whether an output is useful depends on the device’s job. Efficient devices waste less energy.'});

mk(5,6,{t:'Stored or transferring',concept:'Energy stores and transfers',goal:'Sort examples into energy stores and energy being transferred.',
  brief:'Energy can be stored, or it can be on the move from one place to another.',
  predict:{q:'Is a charged battery storing energy?',o:[['store','Storing'],['transfer','Transferring']]},
  play:{engine:'sort',instr:'Stored or being transferred?',bins:[['store','Energy stored'],['transfer','Energy being transferred']],
    items:[['battery','A charged battery in a drawer','store','Its energy is stored chemically.'],['food','Food in your lunchbox','store','It stores chemical energy.'],['fuel','Fuel in a boat tank','store','It stores chemical energy.'],['bank','A charged power bank','store','Stored for later.'],['bulb','A glowing bulb','transfer','Energy is leaving as light and heat.'],['fan','A spinning fan','transfer','Energy is moving the air.'],['loop','A closed circuit lighting a lamp','transfer','Energy is carried to the lamp.']]},
  explain:[{q:'When a torch is switched on, what happens to the battery’s energy?',o:[['transfer','It is transferred through the circuit to the bulb',1,'Yes. Stored energy becomes energy on the move.'],['make','The battery makes new energy',0,'Does a battery create energy?'],['stay','It stays in the battery',0,'Then how does the bulb light?']]}],
  transfer:{intro:'At the beach.',fig:{type:'solar',set:{panel:'yes',site:'sun',storage:'yes',time:'day'}},qs:[{q:'A solar battery store has been charged all day and nothing is switched on. Its energy is…',o:[['store','Stored',1,'Yes. Ready for later.'],['transfer','Being transferred to the lamp',0,'Is the lamp on?'],['gone','Gone',0,'Charging fills a store.']]}]},
  hints:{play:['Ask: is anything happening right now?','If it is waiting, it is a store.','Worked example: food → stored; glowing bulb → transferring.'],explain:['Where does the energy go when switched on?','To the bulb.'],transfer:['Is anything switched on?','Then it is stored.']},
  learned:'Batteries, food and fuel are energy stores. A lit bulb or spinning fan shows energy being transferred.'});

mk(5,7,{t:'Shade on the panel',concept:'A system depends on every part',goal:'Find out whether a shaded panel can charge a store for the night.',scene:'solar',
  brief:'This light has a panel and a battery store. Does it matter where the panel is if the light is only used at night?',
  predict:{q:'If the panel is in shade, will the lamp still work at night?',o:[['yes','Yes, the store will help'],['no','No']],r:[['store','There is a battery store'],['charge','The store needs charging by day'],['unsure','I’m not sure']]},
  play:{engine:'solar',initial:{panel:'yes',site:'sun',storage:'yes',time:'night'},edit:['site','time'],
    reqs:[['Test at night with the panel in open sun.',has((s,r)=>s.time==='night'&&s.site==='sun'&&r.lit)],['Test at night with the panel in shade.',has((s,r)=>s.time==='night'&&s.site==='shade'&&!r.lit)]],
    steps:['Test at night with the panel in open sun.','Move the panel into shade and test at night.']},
  explain:[{q:'Why did the shaded system fail at night?',o:[['charge','The shaded panel couldn’t charge the store during the day',1,'Yes. A store only holds what was put into it.'],['night','Stores don’t work at night',0,'Look at your sunny-spot night test.'],['lamp','The lamp broke',0,'It lit in the other test.']]},
    {q:'Did any result surprise you?',o:[['yes','Yes, the store didn’t help when the panel was shaded',1,'Good. Results that challenge a prediction are useful evidence.'],['no','No, it was obvious',0,'Look at your prediction too.']]}],
  transfer:{intro:'A school entrance light.',fig:{type:'solar',set:{panel:'yes',site:'shade',storage:'yes',time:'night'}},qs:[{q:'This light has a store but its panel is under a tree. What would fix it?',o:[['move','Move the panel into open sun',1,'Yes. The store needs charging.'],['store','Add a second store',0,'Would an empty store help?'],['lamp','Change the lamp',0,'Is the lamp the problem?']]}]},
  hints:{play:['Change only the panel spot.','Keep the time at night.','Worked comparison: sun + store → on at night. Shade + store → off.'],explain:['Where does the store’s energy come from?','From the panel by day.'],transfer:['Is the panel in sun?','Move it.']},
  learned:'A battery store only helps if the panel can charge it. A shaded panel leaves the store empty.'});

mk(5,8,{t:'Charge by day, light by night',concept:'The solar storage chain',goal:'Put the steps of a solar night light in order.',scene:'solar',
  brief:'How does sunshine at noon become light at midnight?',
  predict:{q:'When is the battery store charged?',o:[['day','During the day'],['night','At night']]},
  play:{engine:'sequence',instr:'Put the steps in order.',cards:[['sun','Sunlight reaches the panel by day'],['panel','The panel transfers energy electrically'],['store','The battery store stores the energy chemically'],['night','After dark, the store supplies the circuit'],['lamp','The lamp gives out light and heat']]},
  explain:[{q:'What is the store’s job?',o:[['later','Keep energy from the day for use later',1,'Yes.'],['make','Make energy at night',0,'Stores don’t make energy.'],['light','Give out light',0,'What gives out light?']]}],
  transfer:{intro:'A phone power bank.',fig:{type:'scene',key:'island'},qs:[{q:'A power bank is charged by a small panel, then charges a phone at night. Which step comes in the middle?',o:[['store','The power bank stores energy',1,'Yes. Same chain.'],['phone','The phone screen lights up',0,'That comes last.'],['sun','Sunlight hits the panel',0,'That comes first.']]}]},
  hints:{play:['Start with the sun.','Storing comes before night.','Worked example: sun → panel → store → night → lamp.'],explain:['Look at step 3.','When is the energy used?'],transfer:['What happens between charging and using?','Storing.']},
  learned:'By day the panel charges the store; after dark the store supplies energy to the lamp.'});

mk(5,9,{t:'Observation or interpretation',concept:'Separating results from conclusions',goal:'Sort statements into observations and interpretations.',
  brief:'Scientists separate what they saw from what they think it means.',
  predict:{q:'“The bulb was off in Test 2.” Is that an observation?',o:[['obs','Observation'],['int','Interpretation']]},
  play:{engine:'sort',instr:'Observation or interpretation?',bins:[['obs','Observation (what we saw)'],['int','Interpretation (what we think it means)']],
    items:[['off','The bulb was off in Test 2.','obs','It describes what was seen.'],['on','The bulb was on when foil was used.','obs','It describes what was seen.'],['switch','The switch was closed in every test.','obs','It describes a setting.'],['plastic','Plastic doesn’t conduct.','int','It explains the results.'],['gap','The gap stopped the current.','int','It explains a result.'],['metal','Metals are good conductors.','int','It is a general idea from the results.']]},
  explain:[{q:'Why keep them separate?',o:[['check','So others can check whether the conclusion fits the results',1,'Yes.'],['neat','It looks neater',0,'Think about checking.'],['same','They are the same thing',0,'Look at your two groups.']]}],
  transfer:{intro:'A solar report.',fig:{type:'solar',set:{panel:'yes',site:'shade',storage:'no',time:'day'}},qs:[{q:'Which is an observation?',o:[['obs','The lamp was off with the panel under the palm.',1,'Yes. That is what was seen.'],['int','Shade reduces the panel’s output.',0,'That explains the result.'],['int2','Panels need sunlight.',0,'That is an interpretation.']]}]},
  hints:{play:['Ask: did someone see it, or work it out?','Observations describe a test.','Worked example: “bulb off” → observation.'],explain:['Who checks a conclusion?','Others need the raw results.'],transfer:['Which describes one test?','The lamp was off.']},
  learned:'Observations describe what was seen. Interpretations explain what it means. Keeping them separate lets others check.'});

mk(5,10,{t:'Batteries don’t make energy',concept:'Energy and current misconceptions',goal:'Decide which statements about batteries and current are accurate.',
  brief:'Lots of people mix up energy and current. Sort the statements.',
  predict:{q:'Does a battery contain a packet of current that gets used up?',o:[['yes','Yes'],['no','No']]},
  play:{engine:'sort',instr:'Accurate or not accurate?',bins:[['true','Accurate'],['false','Not accurate']],
    items:[['stores','A battery stores energy chemically.','true','Yes, as a chemical store.'],['transfers','Energy is transferred from the battery to the bulb.','true','Through the circuit.'],['create','A battery creates energy from nothing.','false','Energy is stored, not created.'],['usedup','The bulb uses up the current.','false','Current is the same all around a single loop.'],['flat','A “flat” battery has transferred its stored energy.','true','Its store is empty.'],['packet','A battery holds a packet of current.','false','It stores energy; current is the flow in the loop.']]},
  explain:[{q:'When a battery goes “flat”, what has happened?',o:[['energy','Its stored energy has been transferred',1,'Yes.'],['current','It has run out of current',0,'Current flows; energy is stored.'],['destroy','Its energy was destroyed',0,'Energy isn’t destroyed.']]}],
  transfer:{intro:'A note on the noticeboard.',fig:{type:'scene',key:'path'},qs:[{q:'The note says: “The second bulb gets less current because the first bulb used some.” Is that accurate?',o:[['no','No. In one loop the current is the same all the way round.',1,'Yes.'],['yes','Yes',0,'Look at your “uses up current” card.']]}]},
  hints:{play:['Energy is stored and transferred, never created or destroyed.','Current isn’t used up in a loop.','Worked example: “battery creates energy” → not accurate.'],explain:['What does a battery store?','Energy.'],transfer:['Is current used up?','No.']},
  learned:'Batteries store energy and transfer it through a circuit. They don’t create energy, and current isn’t used up by bulbs.'});

/* ---------- Grade 6 ---------- */
mk(6,1,{t:'Two bulbs one loop',concept:'Series circuits',goal:'Complete a single loop that passes through two identical bulbs.',
  brief:'The noticeboard light has two identical bulbs in one loop. One wire is missing.',
  predict:{q:'With one wire missing, will either bulb light?',o:[['none','Neither'],['one','Just one'],['both','Both']],r:[['loop','The loop is broken'],['near','The nearest bulb gets current first'],['unsure','I’m not sure']]},
  play:{engine:'circuit',layout:'series',initial:{c:{s1:'metal',s2:'metal',s3:'metal',s4:null},sw:'closed'},mats:['metal'],
    reqs:[['Test as you found it.',has((s,r)=>s.connectors.s4==null&&allOff(r))],['Complete the loop and test.',has((s,r)=>isClosed(s)&&allOn(r))]],
    steps:['Test the circuit as you found it.','Add the missing wire and test.']},
  explain:[{q:'Trace the route. Which statement is correct?',o:[['route','Current flows from the battery, through the switch, bulb 1, bulb 2, and back, all in one loop.',1,'Yes. One route, both bulbs on it.'],['usedup','Bulb 1 uses up current so less reaches bulb 2.',0,'Current isn’t used up in a series loop.'],['two','Each bulb has its own separate loop.',0,'Trace your route. Is there more than one?']]},
    {q:'Why was bulb 1 off when the gap was after bulb 2?',o:[['loop','A gap anywhere breaks the single loop',1,'Yes.'],['far','The gap was far away so it didn’t matter',0,'Look at your first test.'],['order','Bulb 1 waits for bulb 2',0,'Bulbs don’t wait.']]}],
  transfer:{intro:'A new two-bulb loop.',fig:{type:'circuit',layout:'series',set:{c:{s1:'metal',s2:null,s3:'metal',s4:'metal'},sw:'closed'}},qs:[{q:'The gap is between the switch and bulb 1. What happens to bulb 2?',o:[['off','It is off too',1,'Yes. One loop, one break.'],['on','It lights',0,'Is the loop complete?']]}]},
  hints:{play:['Test first.','Find the missing wire.','Worked comparison: all four wires + closed switch → both on.'],explain:['Trace the loop with your finger.','Is there one route or two?'],transfer:['One loop?','A break anywhere stops it.']},
  learned:'In a series circuit there is one loop. Current flows through every part and isn’t used up.'});

mk(6,2,{t:'Break anywhere',concept:'Predicting series faults',goal:'Open the loop before, between and after the bulbs, and predict each result.',
  brief:'Where you break a series loop might seem to matter. Test it.',
  predict:{q:'If you break the loop between the bulbs, what happens?',o:[['both','Both bulbs go off'],['one','Only bulb 2 goes off'],['none','Both stay on']],r:[['loop','It is one loop'],['first','Bulb 1 is before the break'],['unsure','I’m not sure']]},
  play:{engine:'circuit',layout:'series',initial:{c:{s1:'metal',s2:'metal',s3:'metal',s4:'metal'},sw:'closed'},mats:['metal'],allowGap:true,lockSwitch:true,
    reqs:[['Break the loop before the bulbs and test.',has((s,r)=>oneGapIn(s,['s1','s2'])&&allOff(r))],['Break it between the bulbs and test.',has((s,r)=>oneGapIn(s,['s3'])&&allOff(r))],['Break it after the bulbs and test.',has((s,r)=>oneGapIn(s,['s4'])&&allOff(r))]],
    steps:['Remove one wire before bulb 1 and test. Put it back after.','Remove only the wire between the bulbs and test.','Remove only the wire after bulb 2 and test.']},
  explain:[{q:'What do all three tests show?',o:[['all','A single break anywhere turns both bulbs off',1,'Yes. Position doesn’t matter in one loop.'],['near','Only the bulb nearest the break goes off',0,'Look at your test log.'],['before','Breaks before the bulbs matter most',0,'Compare all three.']]},
    {q:'What does that tell you about current?',o:[['loop','It needs the whole loop; it doesn’t flow “up to” the break',1,'Yes.'],['usedup','It gets used up before the break',0,'Then bulb 1 would stay on.'],['fast','It flows too fast to see',0,'Look at the results.']]}],
  transfer:{intro:'Festival lights.',fig:{type:'scene',key:'pathLit'},qs:[{q:'A string of lights is wired in one loop. One connection breaks near the end. What happens?',o:[['all','All the lights go off',1,'Yes. Same idea.'],['end','Only the last light goes off',0,'Is it one loop?'],['none','Nothing',0,'Is the loop complete?']]}]},
  hints:{play:['Tap a wire and choose “Remove it”.','Put it back before removing the next one.','Worked comparison: any single gap → both bulbs off.'],explain:['Compare your three tests.','Did position matter?'],transfer:['Is it one loop?','Any break stops all.']},
  learned:'In a single series loop, a break anywhere stops the current everywhere, so all the bulbs go off.'});

mk(6,3,{t:'Design the night light',concept:'Evaluating a system against requirements',goal:'Design a solar path light for a shaded site that works after dark.',scene:'solar',
  brief:'The path is under palm trees and must be lit after dark. The panel can be placed away from the lamp. Design a system that meets both requirements.',
  predict:{q:'Which parts will your design need?',o:[['both','Panel in sun and a battery store'],['panel','Just a panel'],['shade','Panel in shade next to the lamp']]},
  play:{engine:'solar',initial:{panel:'no',site:'shade',storage:'no',time:'night'},edit:['panel','site','storage','time'],
    reqs:[['Find a design that lights the lamp after dark.',has((s,r)=>s.time==='night'&&r.lit)],['Test a design that fails, to see a limit.',has((s,r)=>s.time==='night'&&!r.lit&&s.panel==='yes')]],
    steps:['Choose parts and test after dark.','Now test one design that fails after dark, so you know a limit.']},
  explain:[{q:'Justify your design.',o:[['just','Panel in open sun charges the store by day; the store lights the lamp after dark',1,'Yes. Each part meets a requirement.'],['panel','The panel lights the lamp at night',0,'Look at your night tests without a store.'],['shade','Putting the panel next to the lamp is best',0,'The lamp is in shade.']]},
    {q:'Which condition could limit your design in the real world?',o:[['cloud','Several cloudy days could leave the store only partly charged',1,'Yes. A justified conclusion names its limits.'],['none','None. It will always work.',0,'Can you think of weather that matters?'],['moon','A full moon',0,'Moonlight is far too dim.']]}],
  transfer:{intro:'A new site: the jetty.',fig:{type:'solar',set:{panel:'yes',site:'shade',storage:'yes',time:'night'}},qs:[{q:'This design has a store, but the panel is shaded. What would you change first?',o:[['move','Move the panel into open sun',1,'Yes. The store needs charging.'],['remove','Remove the store',0,'Then what lights it at night?'],['bulb','Add another lamp',0,'Would that help charging?']]},
    {q:'Why is “it will work every night” too strong a claim?',o:[['limits','Charging depends on weather and the model is simplified',1,'Yes. State the limit.'],['fine','It isn’t too strong',0,'Think about cloudy weeks.']]}]},
  hints:{play:['You can change all four settings.','Think: what works after dark? What charges it?','Worked comparison: panel in sun + store → on after dark.'],explain:['Name what each part does.','What could stop charging?'],transfer:['Where is the panel?','Then think about limits.']},
  learned:'A good design meets every requirement: a panel in suitable light charges a store, which lights the lamp after dark. Weather can still limit it.'});

mk(6,4,{t:'Find the series fault',concept:'Diagnosing a series circuit',goal:'Find a hidden fault in a two-bulb loop.',
  brief:'Both bulbs on the noticeboard are off. The switch is closed. Find the fault.',
  predict:{q:'If both bulbs are off, where might the fault be?',o:[['any','Anywhere in the loop'],['bulb','In a bulb']]},
  play:{engine:'circuit',layout:'series',initial:{c:{s1:'metal',s2:'metal',s3:'plastic',s4:'metal'},sw:'closed'},mats:['metal','plastic'],
    reqs:[['Test as you found it.',has(s=>s.connectors.s3==='plastic'&&isClosed(s))],['Fix the fault and light both bulbs.',has((s,r)=>allOn(r))]],
    steps:['Test as you found it.','Follow the path, find the fault, fix it and test.']},
  explain:[{q:'Why were both bulbs off, not just bulb 2?',o:[['loop','The plastic broke the single loop, so no current flowed anywhere',1,'Yes.'],['before','Bulb 1 used up the current',0,'Current isn’t used up.'],['bulb','Both bulbs were broken',0,'They lit after one fix.']]}],
  transfer:{intro:'Another two-bulb loop.',fig:{type:'circuit',layout:'series',set:{c:{s1:'metal',s2:'metal',s3:'metal',s4:'wood'},sw:'closed'}},qs:[{q:'Which part is the fault?',tap:true,o:[['s4','Bulb 2 back to battery −',1,'Yes. Wood is an insulator.'],['b1','Bulb 1',0,'Check the connectors.'],['sw','Switch',0,'It is closed.']]}]},
  hints:{play:['Use Follow the path.','Look for a non-metal connector.','Worked comparison: all metal + closed → both on.'],explain:['Was the loop complete?','One break stops both.'],transfer:['Check every connector.','Find the insulator.']},
  learned:'In a series loop, one fault anywhere turns every bulb off. Diagnose by following the whole loop.'});

mk(6,5,{t:'Current isn’t used up',concept:'Series circuit ideas',goal:'Decide which statements about series circuits are accurate.',
  brief:'Sort these claims about a two-bulb series loop. Use what your tests showed.',
  predict:{q:'Is the current smaller after the first bulb?',o:[['yes','Yes'],['no','No']]},
  play:{engine:'sort',instr:'Accurate or not accurate?',bins:[['true','Accurate'],['false','Not accurate']],
    items:[['same','The current is the same all the way round one loop.','true','Nothing is used up.'],['energy','Energy is transferred to both bulbs.','true','Each bulb gives out light and heat.'],['first','The first bulb uses up some current.','false','Current isn’t used up.'],['break','A break anywhere stops both bulbs.','true','Your tests showed this.'],['near','Bulbs near the battery always get more current.','false','There is one route.'],['own','Each bulb has its own loop.','false','That would be a different circuit.']]},
  explain:[{q:'Which evidence supports “current isn’t used up”?',o:[['break','A break after bulb 2 turned bulb 1 off too',1,'Yes. Current needs the whole loop.'],['bright','Bulb 1 looked brighter',0,'Brightness wasn’t measured.'],['none','There is no evidence',0,'Look at Break anywhere.']]}],
  transfer:{intro:'A classmate’s claim.',fig:{type:'circuit',layout:'series',set:{c:{s1:'metal',s2:'metal',s3:'metal',s4:'metal'},sw:'closed'}},qs:[{q:'“Bulb 2 only lights because bulb 1 leaves some current for it.” Accurate?',o:[['no','Not accurate',1,'Yes. The same current flows through both.'],['yes','Accurate',0,'Is current used up?']]}]},
  hints:{play:['Think about your break tests.','Current isn’t used up.','Worked example: “break anywhere stops both” → accurate.'],explain:['Which test showed the whole loop matters?','The break after bulb 2.'],transfer:['Is current used up?','No.']},
  learned:'In a series loop the same current flows through every part. Energy, not current, is transferred to the bulbs.'});

mk(6,6,{t:'What the model can’t tell you',concept:'Limits of a model',goal:'Sort questions the game’s model can answer from ones it can’t.',
  brief:'Every model simplifies. Knowing its limits is part of good science.',
  predict:{q:'Can this model tell you how long a real battery lasts?',o:[['yes','Yes'],['no','No']]},
  play:{engine:'sort',instr:'Can the model answer it?',bins:[['can','The model shows this'],['cannot','The model can’t show this']],
    items:[['loop','Whether the loop is complete','can','The model checks the path.'],['cond','Whether a material conducts in the model','can','Each material is set as conductor or insulator.'],['series','Whether a break turns all series bulbs off','can','The model traces the loop.'],['bright','The exact brightness of real bulbs','cannot','Brightness isn’t modelled.'],['life','How long a real battery lasts','cannot','The model has no time or battery size.'],['cloud','How much a cloudy day reduces charging','cannot','The solar model only has sun or shade.']]},
  explain:[{q:'Why state the model’s limits?',o:[['honest','So conclusions don’t claim more than the evidence shows',1,'Yes.'],['wrong','Because the model is wrong',0,'It is simplified, not wrong.'],['none','There is no reason',0,'Think about claims.']]}],
  transfer:{intro:'A report.',fig:{type:'scene',key:'island'},qs:[{q:'A report says: “The game proves foil gives brighter light than wire.” What is wrong?',o:[['bright','The model doesn’t measure brightness',1,'Yes.'],['foil','Foil doesn’t conduct',0,'It does in the model.'],['nothing','Nothing',0,'What does the model measure?']]}]},
  hints:{play:['Ask: did the model ever show this?','Brightness and time aren’t in the model.','Worked example: loop complete → can show.'],explain:['What happens if we claim too much?','Conclusions should match evidence.'],transfer:['Does the model show brightness?','No.']},
  learned:'A model simplifies. State its limits so conclusions don’t claim more than the evidence shows.'});

mk(6,7,{t:'Supported conclusions',concept:'Linking claims to evidence',goal:'Sort conclusions into ones the results support and ones they don’t.',
  brief:'Results: Test A, metal connector, bulb on. Test B, plastic connector, bulb off. Test C, foil connector, bulb on. Switch closed and everything else the same in all three.',
  predict:{q:'Do these results show that foil conducts?',o:[['yes','Yes'],['no','No']]},
  play:{engine:'sort',instr:'Do tests A, B and C support it?',bins:[['yes','Supported'],['no','Not supported']],
    items:[['foil','Foil conducted in this model circuit.','yes','Test C: bulb on.'],['plastic','Plastic didn’t conduct in this circuit.','yes','Test B: bulb off.'],['all','All metals conduct.','no','Only two metals were tested.'],['bright','Foil gives more light than wire.','no','Brightness wasn’t measured.'],['material','Changing the connector material changed the result.','yes','Only the material changed.'],['battery','The battery was stronger in Test A.','no','The battery was the same.']]},
  explain:[{q:'Why is “All metals conduct” not supported by these tests alone?',o:[['few','Only two metals were tested',1,'Yes. More evidence would be needed.'],['false','Because it is false',0,'It may be true, but these tests don’t show all metals.'],['plastic','Because plastic was tested',0,'Think about how many metals.']]}],
  transfer:{intro:'Solar results.',fig:{type:'solar',set:{panel:'yes',site:'sun',storage:'yes',time:'night'}},qs:[{q:'Result: a panel in sun with a store lit the lamp after dark once. Which conclusion is supported?',o:[['once','In this model, this design lit the lamp after dark',1,'Yes. Matches the evidence.'],['always','This design always works in every weather',0,'Was weather tested?'],['best','This is the best design possible',0,'Were others compared?']]}]},
  hints:{play:['Ask: which test shows it?','No test means not supported.','Worked example: “foil conducted” → Test C.'],explain:['How many metals were tested?','Two.'],transfer:['What was actually tested?','One design, once.']},
  learned:'A supported conclusion matches what was tested. Claims about things not tested need more evidence.'});

mk(6,8,{t:'Repeat to be sure',concept:'Repeated evidence',goal:'Repeat tests to check results are consistent.',
  brief:'One result can be a mistake. Repeat your tests to be sure.',
  predict:{q:'If you repeat the same test, will you get the same result?',o:[['yes','Yes, in this model'],['no','Maybe not']]},
  play:{engine:'circuit',layout:'series',initial:{c:{s1:'metal',s2:'metal',s3:'metal',s4:'metal'},sw:'closed'},mats:['metal','plastic'],
    reqs:[['Run the same test twice.',T=>{const c={};T.forEach(x=>{const k=JSON.stringify(x.s);c[k]=(c[k]||0)+1;});return Object.values(c).some(v=>v>=2);}],
      ['Change one thing, then run that test twice too.',T=>{const c={};T.forEach(x=>{const k=JSON.stringify(x.s);c[k]=(c[k]||0)+1;});return Object.values(c).filter(v=>v>=2).length>=2;}]],
    steps:['Press Test twice without changing anything.','Change one thing, then press Test twice.']},
  explain:[{q:'Why repeat tests?',o:[['check','To check the result is consistent, not a one-off mistake',1,'Yes.'],['time','To use up time',0,'Think about mistakes.'],['change','To get a different answer',0,'Did it change?']]},
    {q:'In real life, why might repeats differ when the model’s don’t?',o:[['real','Real parts can have loose connections or worn batteries',1,'Yes. The model is idealised.'],['never','They never differ',0,'Think about real wires.'],['magic','Electricity is random',0,'Think about real parts.']]}],
  transfer:{intro:'A classmate’s data.',fig:{type:'scene',key:'island'},qs:[{q:'A real test gave “bulb on” twice and “bulb off” once with the same setup. What should they do?',o:[['check','Check the connections and repeat again',1,'Yes. Investigate the odd result.'],['ignore','Ignore the odd one without checking',0,'Is that careful?'],['stop','Stop: the data is useless',0,'Repeats help find problems.']]}]},
  hints:{play:['Press Test twice.','Then change one thing.','Worked example: test A twice, test B twice.'],explain:['What could go wrong with one test?','A mistake.'],transfer:['What could cause the odd result?','A loose connection.']},
  learned:'Repeating tests checks that results are consistent. An odd result in real life is a reason to investigate.'});

mk(6,9,{t:'Sun to light, step by step',concept:'Energy through a whole system',goal:'Order the energy transfers in a solar night light.',scene:'solar',
  brief:'Trace the energy from the sun all the way to the path at night.',
  predict:{q:'Where does the energy end up?',o:[['surround','In the surroundings, as light and heat'],['battery','Back in the battery']]},
  play:{engine:'sequence',instr:'Order the transfers.',cards:[['sun','Light from the sun reaches the panel'],['panel','The panel transfers energy electrically'],['store','The battery store stores it chemically'],['circuit','After dark, the circuit transfers energy electrically to the lamp'],['lamp','The lamp gives out light and heat'],['surround','The energy spreads into the surroundings']]},
  explain:[{q:'Is any energy created or destroyed in this chain?',o:[['no','No. It is transferred and stored, never created or destroyed.',1,'Yes.'],['created','The panel creates it',0,'Where did it come from?'],['destroyed','The lamp destroys it',0,'Where does it go?']]}],
  transfer:{intro:'A solar water pump.',fig:{type:'scene',key:'island'},qs:[{q:'A solar pump lifts water to a tank. What is the final useful energy?',o:[['tank','Water raised up in the tank (a gravity store)',1,'Yes. A new store at the end.'],['light','Light',0,'What does a pump do?'],['none','None',0,'Something useful happened.']]}]},
  hints:{play:['Start with the sun.','Storing comes before after dark.','Worked example: sun → panel → store → circuit → lamp → surroundings.'],explain:['Does the chain start with nothing?','No.'],transfer:['What does a pump do?','Lifts water.']},
  learned:'In a solar night light, energy moves from the sun to the panel, into a store, through the circuit to the lamp, and out to the surroundings.'});

mk(6,10,{t:'Design for a cloudy week',concept:'Design under constraints',goal:'Choose design changes that help a solar light through a cloudy week.',scene:'solar',
  brief:'Weather reports say a cloudy week is coming. Which design choices help the path light keep working?',
  predict:{q:'Would a bigger battery store help?',o:[['yes','Yes'],['no','No']]},
  play:{engine:'sort',instr:'Does each choice help or not?',bins:[['help','Helps'],['no','Doesn’t help']],
    items:[['store','A bigger battery store','help','It holds more energy for dull days.'],['open','Panel in the most open spot','help','It collects what light there is.'],['led','An efficient LED lamp','help','It uses less stored energy.'],['timer','Switch the lamp off late at night when nobody walks there','help','It saves stored energy.'],['tree','Move the panel under the tree','no','Less light reaches it.'],['allday','Leave the lamp on all day','no','It wastes stored energy.']]},
  explain:[{q:'Which conclusion is justified?',o:[['reduce','These choices reduce the risk of failure, but very long cloudy spells could still drain the store.',1,'Yes. Justified, with a limitation.'],['never','With these choices it can never fail.',0,'What if it’s cloudy for weeks?'],['nothing','Nothing helps.',0,'Look at your helps group.']]}],
  transfer:{intro:'A clinic’s night light.',fig:{type:'solar',set:{panel:'yes',site:'sun',storage:'yes',time:'night'}},qs:[{q:'The clinic light must work every night. Which extra step is most sensible?',o:[['backup','Keep a backup supply for long cloudy spells',1,'Yes. It handles the limitation.'],['ignore','Ignore the weather',0,'Is that safe for a clinic?'],['remove','Remove the store',0,'Then what works at night?']]}]},
  hints:{play:['Ask: does it store more, collect more or use less?','Shade and waste don’t help.','Worked example: bigger store → helps.'],explain:['Is any design perfect?','State a limit.'],transfer:['What if clouds last weeks?','A backup.']},
  learned:'Good designs collect more, store more and waste less, and still state what could make them fail.'});
